SELECT json_build_object('columns',(SELECT json_agg(x ORDER BY table_name,ordinal_position) FROM (SELECT table_name,column_name,ordinal_position,data_type,udt_name,is_nullable FROM information_schema.columns WHERE table_schema='public')x),'relations',(SELECT json_agg(x ORDER BY name) FROM (SELECT c.relname AS name,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relowner=current_user::regrole AS correct_owner FROM pg_class c WHERE c.relnamespace='public'::regnamespace)x),'function_count',(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace),'foreign_server_count',(SELECT count(*) FROM pg_foreign_server),'event_trigger_count',(SELECT count(*) FROM pg_event_trigger),'trigger_count',(SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace='public'::regnamespace),'extra_extensions',(SELECT count(*) FROM pg_extension WHERE extname<>'plpgsql'));
